package local.skyfamily;
import android.app.AlertDialog;import android.graphics.*;import android.text.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
public class SpatialNotebookActivity extends RefinedActivity {
 SpatialPage sheet;LinearLayout metadataRow;View homePhotos;
 @Override void page(String title){super.page(title);sheet=null;metadataRow=null;}
 @Override LinearLayout photoPanel(){LinearLayout panel=super.photoPanel();homePhotos=panel;return panel;}
 @Override void home(){homePhotos=null;super.home();if(homePhotos==null||homePhotos.getParent()!=body)return;View photos=homePhotos;body.removeView(photos);if(getResources().getConfiguration().screenWidthDp>=760&&body.getChildCount()>3&&body.getChildAt(3) instanceof LinearLayout){LinearLayout day=(LinearLayout)body.getChildAt(3);body.removeViewAt(3);day.setOrientation(1);for(int i=0;i<day.getChildCount();i++){LinearLayout.LayoutParams size=(LinearLayout.LayoutParams)day.getChildAt(i).getLayoutParams();size.width=-1;size.weight=0;day.getChildAt(i).setLayoutParams(size);}LinearLayout featured=new LinearLayout(this);addPanel(featured,day,1,true);addPanel(featured,photos,1,true);body.addView(featured,3);}else body.addView(photos,Math.min(3,body.getChildCount()));}
 @Override boolean focusEligible(){if(sheet!=null&&sheet.mode==SpatialPage.TEXT)return false;return super.focusEligible();}
 @Override void updateDock(){super.updateDock();if(sheet!=null&&petDock!=null)petDock.setVisibility(View.GONE);}
 @Override SpannableStringBuilder decodeNote(String source)throws Exception{if(source.startsWith(SpatialPage.PREFIX))return new SpannableStringBuilder(new JSONObject(source.substring(SpatialPage.PREFIX.length())).getString("text"));return super.decodeNote(source);}
 void noteTool(int mode){if(sheet==null)return;sheet.setTool(mode);if(noteInk!=null)noteInk.writing=mode==SpatialPage.PEN||mode==SpatialPage.HIGHLIGHT;if(mode!=SpatialPage.TEXT){noteTitle.clearFocus();noteSection.clearFocus();}scheduleFocus();}
 @Override void schoolNote(String id){page("School note");try{JSONObject record=unsaved.containsKey(id)?unsaved.get(id):db().one("pages",id);if(record==null){schoolHome();return;}StudyInk.Model legacy=StudyInk.Model.parse(record.optString("ink","[]"));JSONArray references=new JSONArray(record.optString("refs","[]"));SpatialPage document=new SpatialPage(this,record.optString("body"),record.optString("ink","[]"),legacy,()->changedSchool());sheet=document;noteClass=record.optString("notebook");noteRefs=references;noteInk=new StudyInk(this,legacy,()->changedSchool());noteText=new EditText(this);metadataRow=new LinearLayout(this);noteTitle=new EditText(this);noteTitle.setText(record.optString("title"));noteTitle.setHint("Page title");noteTitle.setSingleLine(true);noteTitle.setFilters(new InputFilter[]{new InputFilter.LengthFilter(120)});noteSection=new EditText(this);noteSection.setText(record.optString("section","Notes"));noteSection.setHint("Section");noteSection.setSingleLine(true);noteSection.setFilters(new InputFilter[]{new InputFilter.LengthFilter(80)});metadataRow.addView(noteTitle,new LinearLayout.LayoutParams(0,dp(54),2));metadataRow.addView(noteSection,new LinearLayout.LayoutParams(0,dp(54),1));fillWorkspace();body.addView(metadataRow);LinearLayout toolbar=toolsBar();FrameLayout workspace=new FrameLayout(this);workspace.addView(document,new FrameLayout.LayoutParams(-1,-1));refList=new LinearLayout(this);refList.setOrientation(1);ScrollView referencePane=new ScrollView(this);referencePane.addView(refList);workspace.addView(referencePane,new FrameLayout.LayoutParams(-1,-1));referencePane.setVisibility(View.GONE);body.addView(workspace,new LinearLayout.LayoutParams(-1,0,1));savedStatus=paperText(unsaved.containsKey(id)?"Unsaved draft loaded":"Saved on this device",14,MUTE);body.addView(savedStatus);tool(toolbar,"Class",()->notebook(noteClass));tool(toolbar,"Save",()->{dirty=true;flushSchool();});String[] names={"Text","Pen","Highlight","Move","Scroll"};for(int i=0;i<names.length;i++){final int mode=i;tool(toolbar,names[i],()->{referencePane.setVisibility(View.GONE);document.setVisibility(View.VISIBLE);noteTool(mode);});}tool(toolbar,"Undo",()->document.history(false));tool(toolbar,"Redo",()->document.history(true));tool(toolbar,"Bold",()->document.format("b"));tool(toolbar,"Italic",()->document.format("i"));tool(toolbar,"Underline",()->document.format("u"));tool(toolbar,"Heading",()->document.format("h"));tool(toolbar,"Bullet",()->document.prefix("• "));tool(toolbar,"Checklist",()->document.prefix("[ ] "));tool(toolbar,"Zoom +",()->document.zoom(1.25f));tool(toolbar,"Zoom -",()->document.zoom(.8f));tool(toolbar,"PDF links",()->{document.setVisibility(View.GONE);referencePane.setVisibility(View.VISIBLE);});tool(toolbar,"More",()->new AlertDialog.Builder(this).setItems(new String[]{"Wider text box","Narrower text box","Larger text","Smaller text","Delete selected text box","Link bookshelf PDF","Delete school page"},(dialog,which)->{if(which<5)document.adjust(which);else if(which==5)linkPdf();else new AlertDialog.Builder(this).setMessage("Delete this school page and its text/drawing? PDFs are not deleted.").setPositiveButton("Delete",(confirm,value)->attempt(()->{String current=noteId,parent=noteClass;schoolTimer.removeCallbacksAndMessages(null);dirty=false;noteId="";db().exec("DELETE FROM pages WHERE id=?",current);unsaved.remove(current);notebook(parent);})).setNegativeButton("Cancel",null).show();}).show());noteId=id;dirty=unsaved.containsKey(id);renderRefs();TextWatcher watcher=new TextWatcher(){public void beforeTextChanged(CharSequence text,int a,int c,int f){}public void onTextChanged(CharSequence text,int a,int b,int c){changedSchool();}public void afterTextChanged(Editable text){}};noteTitle.addTextChangedListener(watcher);noteSection.addTextChangedListener(watcher);updateDock();}catch(Exception error){dirty=false;noteId="";sheet=null;page("School note unavailable");text("Cannot load this note safely. Existing saved data was not replaced.");button("Back to School",()->schoolHome());return;}}
 @Override void flushSchool(){if(sheet==null){super.flushSchool();return;}schoolTimer.removeCallbacksAndMessages(null);if(!dirty||noteId.isEmpty())return;try{String title=noteTitle.getText().toString().trim(),section=noteSection.getText().toString().trim();if(title.isEmpty())title="Untitled page";if(section.isEmpty())section="Notes";String body=SpatialPage.PREFIX+sheet.json(),ink=noteInk.model.json(),refs=noteRefs.toString();JSONObject draft=new JSONObject().put("id",noteId).put("notebook",noteClass).put("title",title).put("section",section).put("body",body).put("ink",ink).put("refs",refs);unsaved.put(noteId,draft);db().exec("UPDATE pages SET section=?,title=?,body=?,ink=?,refs=?,updated=? WHERE id=?",section,title,body,ink,refs,System.currentTimeMillis(),noteId);unsaved.remove(noteId);dirty=false;savedStatus.setText("Saved on this device / "+new Date());}catch(Exception error){if(savedStatus!=null)savedStatus.setText("NOT SAVED / keep this page open and check storage");toast("School note save failed");}}
 @Override void normalize(View view){super.normalize(view);if(sheet!=null&&metadataRow!=null&&(view==body||view.getId()==android.R.id.content)){int visibility=sheet.editorFocused()?View.GONE:View.VISIBLE;if(metadataRow.getVisibility()!=visibility)metadataRow.setVisibility(visibility);}}
}
